from google.cloud import vision


def describe_image(payload, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    response = client.web_detection(
        image=vision.Image(content=payload["image_bytes"])
    )
    if response.error.message:
        raise RuntimeError(response.error.message)

    if response.web_detection and response.web_detection.best_guess_labels:
        return {"description": response.web_detection.best_guess_labels[0].label}
    return {"description": "No description found."}

from google.cloud import vision


def detect_image_text(payload, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    response = client.text_detection(
        image=vision.Image(content=payload["image_bytes"])
    )
    if response.error.message:
        raise RuntimeError(response.error.message)

    texts = [text.description for text in response.text_annotations]
    return {"detected_text": texts[0] if texts else ""}

from google.cloud import vision


def score_image_safety(payload, config=None):
    config = config or {}
    client = vision.ImageAnnotatorClient()
    response = client.safe_search_detection(
        image=vision.Image(content=payload["image_bytes"])
    )
    if response.error.message:
        raise RuntimeError(response.error.message)

    safe_search_annotation = response.safe_search_annotation
    return {
        "adult": safe_search_annotation.adult.name,
        "spoof": safe_search_annotation.spoof.name,
        "medical": safe_search_annotation.medical.name,
        "violence": safe_search_annotation.violence.name,
        "racy": safe_search_annotation.racy.name,
    }

from google.cloud import vision

def get_vision_client():
    return vision.ImageAnnotatorClient()

import base64

def encode_image_to_base64(image_bytes):
    return base64.b64encode(image_bytes).decode("utf-8")

def decode_base64_to_image(base64_string):
    return base64.b64decode(base64_string)

def normalize_labels_response(response):
    return {"labels": [
        {"name": label.description, "confidence": label.score}
        for label in response.label_annotations
    ]}

def normalize_text_detection_response(response):
    texts = [text.description for text in response.text_annotations]
    return {"detected_text": texts[0] if texts else ""}

def normalize_safe_search_response(response):
    safe_search_annotation = response.safe_search_annotation
    return {
        "adult": safe_search_annotation.adult.name,
        "spoof": safe_search_annotation.spoof.name,
        "medical": safe_search_annotation.medical.name,
        "violence": safe_search_annotation.violence.name,
        "racy": safe_search_annotation.racy.name,
    }

from google.cloud import translate_v2 as translate

def translate_alt_text(payload, config=None):
    config = config or {}
    translate_client = translate.Client()

    text_to_translate = payload["alt_text"]
    target_language = payload.get("target_language", "es")

    result = translate_client.translate(text_to_translate, target_language=target_language)
    return {"translated_text": result["translatedText"]}

from google.cloud import language_v1

def check_visual_safety_text(payload, config=None):
    config = config or {}
    client = language_v1.LanguageServiceClient()

    text_content = payload["text_content"]
    document = language_v1.Document(content=text_content, type_=language_v1.Document.Type.PLAIN_TEXT)

    # Available categories: https://cloud.google.com/natural-language/docs/categories
    # We'll use the moderateText method for explicit safety checks
    response = client.moderate_text(document=document)

    safety_scores = {}
    for category_mention in response.moderation_categories:
        safety_scores[category_mention.name] = category_mention.score

    return {"safety_scores": safety_scores}
